function setTheme(theme){state.theme=theme;document.documentElement.dataset.theme=theme;$('#theme-label').textContent=theme==='dark'?'Light mode':'Dark mode';$('#theme-icon').textContent=theme==='dark'?'☀':'◐';save()}
