publishCurriculum();
function renderFilters(){
 const boards=uniq(STUDY_DATA.map(e=>e.board)); if(!boards.includes(current.board))current.board=boards[0]; fillSelect($('#board-filter'),boards,current.board);
 const grades=uniq(STUDY_DATA.filter(e=>e.board===current.board).map(e=>e.grade));if(!grades.includes(current.grade))current.grade=grades[0];fillSelect($('#grade-filter'),grades,current.grade);
 const subs=uniq(STUDY_DATA.filter(e=>e.board===current.board&&e.grade===current.grade).map(e=>e.subject));if(!subs.includes(current.subject))current.subject=subs[0];fillSelect($('#subject-filter'),subs,current.subject);
 const notice = current.board==='Cambridge IGCSE' ? 'Cambridge IGCSE is a two-year qualification, so topics are shown as one 9–10 pathway rather than falsely split by school year.' : current.board.includes('AS & A') ? 'Cambridge content is organised by qualification stage. Schools may sequence individual topics differently.' : 'CBSE topics are organised by class and subject.';
 $('#curriculum-notice').textContent=notice; renderTopicList(); populateQuizFilters(); renderPlannerBoards();
}
function topicList(){return STUDY_DATA.filter(e=>e.board===current.board&&e.grade===current.grade&&e.subject===current.subject).sort((a,b)=>a.order-b.order)}
function renderTopicList(){const list=topicList();$('#chapter-count').textContent=list.length;$('#chapter-list').innerHTML=list.map(e=>`<button class="chapter-item ${current.topic===e.title?'active':''}" data-topic="${esc(e.title)}">${state.completed.includes(e.id)?'✓ ':''}${esc(e.title)}</button>`).join('');$$('.chapter-item').forEach(b=>b.onclick=()=>openTopic(b.dataset.topic));if(current.topic&&!list.some(e=>e.title===current.topic)){current.topic=null;$('#reader-view').classList.add('hidden');$('#reader-empty').classList.remove('hidden')}}
function deepSections(e){
 const formulas=e.formulas.length?`<div class="formula-list">${e.formulas.map(f=>`<div class="formula">${esc(f)}</div>`).join('')}</div>`:'<p>No single formula defines this topic. Focus on the relationships, definitions and reasoning steps.</p>';
 const kp=e.keyPoints.map(p=>`<li>${esc(p)}</li>`).join('');
 const method=e.method.map((p,i)=>`<li><strong>Step ${i+1}.</strong> ${esc(p)}</li>`).join('');
 const mistakes=e.mistakes.map(p=>`<li>${esc(p)}</li>`).join('');
 return `<div class="note-prose">
 <section class="note-section"><h3>1. Big picture</h3><p>${esc(e.summary)}</p><p>${esc(e.lens)}</p><p>Do not treat this chapter as a list of facts. Build a mental model first, then connect definitions, representations and exam methods to that model. When a question changes context, the model is what lets you transfer what you know.</p></section>
 <section class="note-section"><h3>2. Core ideas you should be able to explain</h3><ul>${kp}</ul><div class="concept-grid"><div class="concept-card"><strong>Definition test</strong><p>Can you define the central terms in your own words, then give an example and a non-example?</p></div><div class="concept-card"><strong>Connection test</strong><p>Can you explain how this topic connects to an earlier idea in the course and why that connection matters?</p></div><div class="concept-card"><strong>Representation test</strong><p>Can you move between a written explanation and the most useful equation, graph, diagram, table or particle model?</p></div><div class="concept-card"><strong>Application test</strong><p>Can you recognise the same principle when the question is placed in an unfamiliar real-world or experimental setting?</p></div></div></section>
 <section class="note-section"><h3>3. Key relationships and formulas</h3>${formulas}<p><strong>How to use formulas well:</strong> write the relationship before substituting, define each symbol, convert units first, rearrange symbolically where possible, and finish by checking whether the size and sign of the answer make sense.</p></section>
 <section class="note-section"><h3>4. A reliable problem-solving method</h3><ol>${method}</ol><div class="worked-box"><h4>Worked reasoning pattern</h4><p>Start by translating the wording into the language of the subject. List the information that is genuinely relevant. Choose one governing idea, carry out the reasoning cleanly, then use the final sentence to answer the exact question rather than merely presenting a calculation.</p></div></section>
 <section class="note-section"><h3>5. Depth and exam interpretation</h3><p>Examiners often test the same knowledge at different depths. A recall question asks you to state or identify. An application question changes the context. An analysis question gives data, a graph, an experiment or competing explanations and expects you to select evidence and justify a conclusion.</p><div class="exam-box"><h4>High-value exam habits</h4><ul><li>Underline command words such as <em>state</em>, <em>calculate</em>, <em>explain</em>, <em>compare</em> and <em>evaluate</em>.</li><li>Match the amount of reasoning to the number of marks.</li><li>Use subject vocabulary, not vague words such as “thing,” “it changes,” or “more strong.”</li><li>For data questions, quote or use the data rather than describing from memory.</li></ul></div></section>
 <section class="note-section"><h3>6. Common mistakes</h3><div class="mistake-box"><ul>${mistakes}</ul><p>Another common error is stopping one step too early. If the question asks “why,” a description is not enough. If it asks for a comparison, both sides must be addressed. If it asks for a calculation, units and sensible rounding matter.</p></div></section>
 <section class="note-section"><h3>7. Revision checklist</h3><ul><li>I can explain the topic without reading these notes.</li><li>I can identify the right method from an unfamiliar question.</li><li>I can use the key equation, graph, diagram or process accurately.</li><li>I can explain at least two common mistakes and how to avoid them.</li><li>I can answer one easy, one standard and one unfamiliar application question.</li></ul></section>
 <section class="note-section"><h3>8. Self-check questions</h3><div class="self-check-box"><ol><li>What is the central idea of <strong>${esc(e.title)}</strong>, in one precise sentence?</li><li>Which representation or relationship is most useful in this topic, and why?</li><li>Describe one situation in which a commonly memorised shortcut would fail.</li><li>How would you recognise a harder exam question on this topic?</li><li>What earlier topic does this depend on most strongly?</li></ol></div></section>
 </div>`;
}
function quickReview(e){return `<div class="quick-card"><h3>Core idea</h3><p>${esc(e.summary)}</p></div><div class="quick-card"><h3>Must know</h3><ul>${e.keyPoints.slice(0,4).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="quick-card"><h3>Formula / relationship</h3><p>${esc(e.formulas.join(' · ')||'Focus on definitions, relationships and process rather than one formula.')}</p></div><div class="quick-card"><h3>Exam move</h3><p>${esc(e.method[0])} ${esc(e.method[1])}</p></div>`}
function openTopic(title){current.topic=title;const e=currentEntry();if(!e)return;state.lastTopic=e.id;save();$('#reader-empty').classList.add('hidden');const view=$('#reader-view');view.classList.remove('hidden');view.classList.remove('content-enter');void view.offsetWidth;view.classList.add('content-enter');$('#note-breadcrumb').textContent=`${e.board} · ${e.grade} · ${e.subject}`;$('#note-title').textContent=e.title;$('#note-summary').textContent=e.summary;$('#detailed-notes').innerHTML=deepSections(e);$('#quick-review').innerHTML=quickReview(e);$('#personal-note-editor').value=state.personalNotes[e.id]||'';updateTopicActions();renderTopicList();updateDashboard()}
function updateTopicActions(){const e=currentEntry();if(!e)return;$('#complete-btn').textContent=state.completed.includes(e.id)?'Completed ✓':'Mark complete';$('#bookmark-btn').textContent=state.bookmarks.includes(e.id)?'Bookmarked':'Bookmark';$('#weak-btn').textContent=state.review.includes(e.id)?'In review queue':'Review'}
function toggle(arr,key){const i=arr.indexOf(key);i>=0?arr.splice(i,1):arr.push(key);save()}
function searchAll(q){q=q.trim().toLowerCase();if(!q)return[];return STUDY_DATA.filter(e=>[e.title,e.subject,e.grade,e.board,e.summary,...e.keyPoints].join(' ').toLowerCase().includes(q)).slice(0,24)}
function showSearch(){const r=searchAll($('#global-search').value),box=$('#search-results');box.classList.toggle('hidden',!r.length);box.innerHTML=r.length?r.map(e=>`<button data-id="${esc(e.id)}"><strong>${esc(e.title)}</strong><span>${esc(e.board)} · ${esc(e.grade)} · ${esc(e.subject)}</span></button>`).join(''):'<p>No matching topic found.</p>';box.querySelectorAll('button').forEach(b=>b.onclick=()=>{const e=STUDY_DATA.find(x=>x.id===b.dataset.id);current={board:e.board,grade:e.grade,subject:e.subject,topic:e.title};renderFilters();openTopic(e.title);box.classList.add('hidden')})}
// Spaced repetition v1: bounded intervals, persisted in existing account state.
const SRS_MINUTE=60*1000, SRS_DAY=24*60*SRS_MINUTE, SRS_MAX_MINUTES=365*24*60;
function scheduledCard(card){
 const record=state.flashcardSchedule?.[card.id];
 return record&&Number.isFinite(record.dueAt)?record:null;
}
function srsCardCatalog(){
 return state.reviewCardCatalog&&typeof state.reviewCardCatalog==='object'?state.reviewCardCatalog:{};
}
function srsDueCards(now=Date.now()){
 const catalog=srsCardCatalog();
 return Object.values(catalog).filter(card=>
  card&&typeof card.id==='string'&&typeof card.front==='string'&&typeof card.back==='string'&&
  scheduledCard(card)&&scheduledCard(card).dueAt<=now)
 .sort((a,b)=>scheduledCard(a).dueAt-scheduledCard(b).dueAt);
}
function reviewTimeLabel(dueAt,now=Date.now()){
 if(!Number.isFinite(dueAt))return 'Not scheduled';
 const remaining=dueAt-now;
 if(remaining<=0)return 'Due now';
 const mins=Math.ceil(remaining/SRS_MINUTE);
 if(mins<60)return 'In '+mins+' min';
 const hours=Math.ceil(remaining/(60*SRS_MINUTE));
 if(hours<24)return 'In '+hours+' hr';
 const days=Math.ceil(remaining/SRS_DAY);
 return days===1?'Tomorrow':'In '+days+' days';
}
function nextSrsInterval(previous,rating){
 const old=Math.max(0,Number(previous?.intervalMinutes)||0);
 const repeats=Math.max(0,Number(previous?.repetitions)||0);
 if(rating==='again')return 1;
 if(rating==='hard')return old<60?10:Math.min(SRS_MAX_MINUTES,Math.max(60,Math.ceil(old*1.2)));
 if(rating==='good')return old<60?24*60:Math.min(SRS_MAX_MINUTES,Math.max(3*24*60,Math.ceil(old*2.2)));
 if(rating==='easy')return old<60?4*24*60:Math.min(SRS_MAX_MINUTES,Math.max(4*24*60,Math.ceil(old*2.8)));
 return 0;
}
function srsSummary(){
 const catalog=srsCardCatalog(),scheduled=state.flashcardSchedule||{};
 const live=Object.keys(catalog).filter(id=>catalog[id]&&scheduled[id]&&Number.isFinite(scheduled[id].dueAt));
 const now=Date.now(),due=live.filter(id=>scheduled[id].dueAt<=now).length;
 const upcoming=live.map(id=>scheduled[id].dueAt).filter(time=>time>now).sort((a,b)=>a-b)[0]||null;
 return {scheduled:live.length,due,upcoming};
}
function renderSrsDashboard(){
 const stats=srsSummary();
 if($('#srs-due-count'))$('#srs-due-count').textContent=stats.due;
 if($('#srs-next-due'))$('#srs-next-due').textContent=stats.due
  ? 'Pick up the cards ready for review.'
  : stats.upcoming?'Next review '+reviewTimeLabel(stats.upcoming).toLowerCase()+'.'
  : 'Rate a card to start scheduling reviews.';
 if($('#srs-progress-due'))$('#srs-progress-due').textContent=stats.due;
 if($('#srs-progress-scheduled'))$('#srs-progress-scheduled').textContent=stats.scheduled;
 if($('#srs-progress-next'))$('#srs-progress-next').textContent=stats.upcoming?reviewTimeLabel(stats.upcoming):'—';
 if($('#srs-progress-note'))$('#srs-progress-note').textContent=stats.due
  ? 'Your '+stats.due+' due card'+(stats.due===1?' is':'s are')+' waiting. Open the review queue to recall them.'
  : stats.scheduled?'You are caught up right now. New reviews will appear as cards become due.'
  : 'Start with a chapter, Workspace, Personal AI or wrong-answer deck. Rate a revealed card to schedule it.';
 if($('#srs-start-due'))$('#srs-start-due').textContent='Review '+stats.due+' due card'+(stats.due===1?'':'s')+' →';
 if($('#srs-progress-open'))$('#srs-progress-open').textContent='Review '+stats.due+' due card'+(stats.due===1?'':'s')+' →';
 renderSmartReviewQueue();
}
function renderSrsCardStatus(){
 const el=$('#srs-card-status'),hint=$('#srs-rating-hint'),card=activeDeck[cardIndex];
 if(!el)return;
 if(!card){
  el.textContent=dueReviewSession?'All caught up — no cards left in this review session.':'Choose a deck to begin.';
  if(hint)hint.textContent='Open a deck and reveal a card to rate your recall.';
  return;
 }
 const record=scheduledCard(card);
 const legacy=state.flashcardState?.[card.id];
 el.textContent=record
  ? (record.dueAt<=Date.now()?'Due now':'Next review '+reviewTimeLabel(record.dueAt).toLowerCase())+
    ' · '+record.reviews+' review'+(record.reviews===1?'':'s')
  : legacy&&legacy!=='New'?'Previous status: '+legacy+' · not scheduled yet':'New card · not scheduled yet';
 if(hint)hint.textContent=cardFlipped
  ? 'How well did you recall it? Choose one rating to schedule your next review.'
  : 'Reveal the answer before rating. Skip / Next does not alter your schedule.';
}
function refreshSrsRatingButtons(){
 const available=!!activeDeck[cardIndex]&&cardFlipped;
 $$('[data-srs-rating]').forEach(b=>b.disabled=!available);
 renderSrsCardStatus();
}
function loadDueReviews(){
 const due=srsDueCards();
 if(!due.length){
  toast('No scheduled cards due. Load a topic and rate cards to get started.');
  location.hash='#flashcards';
  renderSrsDashboard();
  return;
 }
 activeDeck=due;
 dueReviewSession=true;
 cardIndex=0;
 $('#deck-source').value='due';
 renderCard();renderFlashStats();
 location.hash='#flashcards';
 toast('Due review session ready: '+due.length+' card'+(due.length===1?'':'s')+'.');
}
function topicCards(e){const prompts=[['What is the big idea?',e.summary],...e.keyPoints.slice(0,4).map((x,i)=>[`Key idea ${i+1}: ${e.title}`,x])];return prompts.map((x,i)=>({id:`${e.id}|${i}`,front:x[0],back:x[1],source:e.title}))}
function loadDeckFromCurrent(){const e=currentEntry();if(!e)return toast('Open a topic first');dueReviewSession=false;$('#deck-source').value='current';activeDeck=topicCards(e);cardIndex=0;renderCard();renderFlashStats();location.hash='#flashcards'}
function renderCard(){
 const c=activeDeck[cardIndex],card=$('#flashcard');
 cardFlipped=false;card.classList.remove('flipped');card.setAttribute('aria-pressed','false');
 card.setAttribute('aria-label','Flip flashcard to reveal the answer');
 if(!c){
  $('#card-label').textContent=dueReviewSession?'Review complete':'No deck loaded';
  $('#card-front').textContent=dueReviewSession?'You are caught up! Return when the next review is due.':'Open a study topic or choose a saved deck.';
  $('#card-back').textContent='';
  $('#favorite-card').disabled=true;
  $('#next-card').disabled=true;
  refreshSrsRatingButtons();
  return;
 }
 $('#favorite-card').disabled=false;$('#next-card').disabled=false;
 $('#card-label').textContent=(cardIndex+1)+' / '+activeDeck.length+' · '+c.source;
 $('#card-front').textContent=c.front;
 $('#card-back').textContent=c.back;
 $('#favorite-card').textContent=state.favoriteCards.includes(c.id)?'★ Favorite':'☆ Favorite';
 refreshSrsRatingButtons();
}
function renderFlashStats(){
 let n=0,l=0,m=0,due=0,now=Date.now();
 activeDeck.forEach(c=>{
  const record=scheduledCard(c),legacy=state.flashcardState?.[c.id]||'New';
  if(record){
   if(record.dueAt<=now)due++;
   if(record.repetitions>=2&&record.intervalMinutes>=3*24*60)m++;
   else l++;
  }else if(legacy==='Mastered')m++;
  else if(legacy==='Learning')l++;
  else n++;
 });
 $('#fc-new').textContent=n;$('#fc-learning').textContent=l;$('#fc-mastered').textContent=m;
 $('#fc-due').textContent=due;
 renderSrsDashboard();
}
function workspaceCards(note){if(!note)return[];const parts=note.content.split(/\n+/).map(x=>x.trim()).filter(x=>x.length>20).slice(0,12);return parts.map((p,i)=>({id:`ws|${note.id}|${i}`,front:`Explain: ${p.slice(0,80)}${p.length>80?'…':''}`,back:p,source:note.title}))}
function rebuildDeckSources(){
 const previous=$('#deck-source').value;
 let opts='<option value="current">Current study topic</option><option value="due">Due reviews</option><option value="mistakes">Wrong answers</option>';
 state.workspaceNotes.forEach(n=>opts+='<option value="ws:'+esc(n.id)+'">'+esc(n.title)+'</option>');
 $('#deck-source').innerHTML=opts;
 if(previous&&Array.from($('#deck-source').options).some(option=>option.value===previous))$('#deck-source').value=previous;
}
function loadDeckSource(){
 const v=$('#deck-source').value;
 if(v==='due')return loadDueReviews();
 if(v==='current')return loadDeckFromCurrent();
 if(v==='mistakes')return loadMistakeDeck(mistakeRecords());
 if(v.startsWith('ws:')){
  const n=state.workspaceNotes.find(x=>x.id===v.slice(3));
  dueReviewSession=false;activeDeck=workspaceCards(n);cardIndex=0;renderCard();renderFlashStats();
 }
}
function rateFlashcard(rating){
 const card=activeDeck[cardIndex];
 if(!card||!cardFlipped||!['again','hard','good','easy'].includes(rating))return;
 if(!state.flashcardSchedule||typeof state.flashcardSchedule!=='object')state.flashcardSchedule={};
 if(!state.reviewCardCatalog||typeof state.reviewCardCatalog!=='object')state.reviewCardCatalog={};
 if(!state.reviewCardCatalog[card.id]&&Object.keys(state.reviewCardCatalog).length>=500){
  toast('500 saved review cards reached. Reset an old deck before adding more.');return;
 }
 const previous=scheduledCard(card);
 const intervalMinutes=nextSrsInterval(previous,rating);
 if(!intervalMinutes)return;
 const now=Date.now();
 const repetitions=rating==='again'?0:(previous?.repetitions||0)+1;
 state.flashcardSchedule[card.id]={
  intervalMinutes,dueAt:now+intervalMinutes*SRS_MINUTE,lastReviewedAt:now,
  repetitions,lapses:(previous?.lapses||0)+(rating==='again'?1:0),
  reviews:(previous?.reviews||0)+1,lastRating:rating
 };
 state.reviewCardCatalog[card.id]={
  id:card.id,front:String(card.front||'').slice(0,1500),
  back:String(card.back||'').slice(0,1800),source:String(card.source||'Flashcards').slice(0,100)
 };
 state.flashcardState[card.id]=
  repetitions>=2&&intervalMinutes>=3*24*60?'Mastered':'Learning';
 save();
 if(dueReviewSession){
  activeDeck.splice(cardIndex,1);
  if(cardIndex>=activeDeck.length)cardIndex=0;
  renderCard();
  renderFlashStats();
 }else nextCard();
 renderSrsDashboard();
 toast(rating[0].toUpperCase()+rating.slice(1)+' · next review '+reviewTimeLabel(now+intervalMinutes*SRS_MINUTE,now).toLowerCase());
}
function nextCard(){
 if(!activeDeck.length)return;
 cardIndex=(cardIndex+1)%activeDeck.length;renderCard();renderFlashStats();
}
function resetCurrentDeckSchedule(){
 if(!activeDeck.length)return toast('Load a deck first.');
 if(!confirm('Reset ratings and review dates for all cards in this deck?'))return;
 activeDeck.forEach(card=>{
  delete state.flashcardSchedule?.[card.id];
  delete state.reviewCardCatalog?.[card.id];
  delete state.flashcardState?.[card.id];
 });
 save();
 if(dueReviewSession){activeDeck=[];dueReviewSession=false;$('#deck-source').value='current';}
 cardIndex=0;renderCard();renderFlashStats();
 toast('Current deck schedule reset.');
}

// SAT
function satSectionQuestions(){return SAT_QUESTIONS.filter(q=>q.section===satSection)}
function renderSatFilters(){const domains=Object.keys(SAT_DOMAINS[satSection]);fillSelect($('#sat-domain'),domains,$('#sat-domain').value||domains[0]);const domain=$('#sat-domain').value;fillSelect($('#sat-skill'),SAT_DOMAINS[satSection][domain],$('#sat-skill').value||SAT_DOMAINS[satSection][domain][0]);renderSatDomainCards();updateSatSummary()}
function masteryFor(section,domain){const rec=state.satHistory.filter(h=>h.section===section&&(domain?h.domain===domain:true));if(!rec.length)return 0;return Math.round(rec.reduce((a,b)=>a+b.correct,0)/rec.length*100)}
function renderSatDomainCards(){$('#sat-domain-cards').innerHTML=Object.keys(SAT_DOMAINS[satSection]).map(d=>{const m=masteryFor(satSection,d);return `<button class="sat-domain-card" data-domain="${esc(d)}"><div class="domain-top"><strong>${esc(d)}</strong><span>${m}%</span></div><div class="mastery-bar"><span style="width:${m}%"></span></div></button>`}).join('');$$('.sat-domain-card').forEach(b=>b.onclick=()=>{$('#sat-domain').value=b.dataset.domain;renderSatFilters()})}
function updateSatSummary(){const all=state.satHistory;const overall=all.length?Math.round(all.reduce((a,b)=>a+b.correct,0)/all.length*100):0;$('#sat-overall').textContent=overall+'%';$('#hero-sat').textContent=overall+'%';$('#sat-streak').textContent=all.length?`${all.length} SAT questions answered in this browser`:'No SAT practice yet';$('#metric-sat').textContent=overall+'%'}
function startSat(timed=false){const domain=$('#sat-domain').value,skill=$('#sat-skill').value,level=$('#sat-level').value,count=+$('#sat-count').value;let pool=SAT_QUESTIONS.filter(q=>q.section===satSection);if(!timed)pool=pool.filter(q=>q.domain===domain&&q.skill===skill&&q.level===level);if(!pool.length)pool=SAT_QUESTIONS.filter(q=>q.section===satSection&&q.domain===domain&&q.skill===skill);if(pool.length<count){const more=SAT_QUESTIONS.filter(q=>q.section===satSection&&q.domain===domain&&!pool.includes(q));pool=[...pool,...more]}satRun=shuffle([...pool]).slice(0,Math.min(count,pool.length));satIndex=0;satScore=0;if(!satRun.length)return toast('No questions match this filter yet');$('#sat-runner').classList.remove('hidden');renderSatQuestion()}
function renderSatQuestion(){const q=satRun[satIndex];$('#sat-runner').innerHTML=`<div class="runner-top"><div><strong>${esc(q.section)}</strong><div class="runner-meta">${esc(q.domain)} · ${esc(q.skill)} · ${esc(q.level)}</div></div><span>${satIndex+1} / ${satRun.length}</span></div>${q.passage?`<div class="question-passage">${esc(q.passage)}</div>`:''}<div class="question-stem">${esc(q.stem)}</div><div class="options">${q.options.map((o,i)=>`<button class="option-btn" data-i="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><div id="sat-feedback"></div>`;$('#sat-runner').querySelectorAll('.option-btn').forEach(b=>b.onclick=()=>answerSat(+b.dataset.i))}
function answerSat(i){const q=satRun[satIndex],ok=i===q.answer;if(ok)satScore++;state.satHistory.push({date:new Date().toISOString(),section:q.section,domain:q.domain,skill:q.skill,level:q.level,correct:ok?1:0});satMasteryEvidence(q,ok);noteMistakeResult(q,'sat',i,ok,'sat-practice');save();$('#sat-runner').querySelectorAll('.option-btn').forEach((b,idx)=>{b.disabled=true;if(idx===q.answer)b.classList.add('correct');else if(idx===i)b.classList.add('wrong')});$('#sat-feedback').innerHTML=`<div class="explanation"><strong>${ok?'Correct':'Not quite'}</strong><p>${esc(q.explanation)}</p><div class="runner-actions"><span>Set score: ${satScore}/${satIndex+1}</span><button class="button primary compact" id="sat-next">${satIndex===satRun.length-1?'Finish':'Next'}</button></div></div>`;$('#sat-next').onclick=()=>{if(satIndex<satRun.length-1){satIndex++;renderSatQuestion()}else finishSat()};updateSatSummary();updateDashboard()}
function finishSat(){$('#sat-runner').innerHTML=`<div class="quiz-result"><span class="small-label">SAT practice complete</span><h3>${satScore} / ${satRun.length}</h3><p>Review the domains below, then run another targeted set on the weakest one.</p><button class="button primary" id="sat-again">Practice again</button></div>`;$('#sat-again').onclick=()=>startSat(false);renderSatDomainCards()}

// Curriculum quiz from note data
function populateQuizFilters(){const boards=uniq(STUDY_DATA.map(e=>e.board));fillSelect($('#quiz-board'),boards,$('#quiz-board').value||current.board);const b=$('#quiz-board').value;const grades=uniq(STUDY_DATA.filter(e=>e.board===b).map(e=>e.grade));fillSelect($('#quiz-grade'),grades,$('#quiz-grade').value||grades[0]);const g=$('#quiz-grade').value;const subs=uniq(STUDY_DATA.filter(e=>e.board===b&&e.grade===g).map(e=>e.subject));fillSelect($('#quiz-subject'),subs,$('#quiz-subject').value||subs[0]);const s=$('#quiz-subject').value;const topics=STUDY_DATA.filter(e=>e.board===b&&e.grade===g&&e.subject===s);$('#quiz-chapter').innerHTML='<option value="all">Mixed topics</option>'+topics.map(e=>`<option>${esc(e.title)}</option>`).join('')}
function makeCurriculumQuestion(e){const others=shuffle(STUDY_DATA.filter(x=>x.subject===e.subject&&x.id!==e.id)).slice(0,3).map(x=>x.summary);const options=shuffle([e.summary,...others]);return {entry:e,stem:`Which statement best matches ${e.title}?`,options,answer:options.indexOf(e.summary),explanation:e.summary}}
function startQuiz(){const b=$('#quiz-board').value,g=$('#quiz-grade').value,s=$('#quiz-subject').value,t=$('#quiz-chapter').value,n=+$('#quiz-length').value;let pool=STUDY_DATA.filter(e=>e.board===b&&e.grade===g&&e.subject===s&&(t==='all'||e.title===t));if(pool.length<n)pool=STUDY_DATA.filter(e=>e.board===b&&e.grade===g&&e.subject===s);activeQuiz=shuffle(pool).slice(0,Math.min(n,pool.length)).map(makeCurriculumQuestion);quizIndex=0;quizScore=0;$('#quiz-setup').classList.add('hidden');$('#quiz-result').classList.add('hidden');$('#quiz-runner').classList.remove('hidden');renderQuizQuestion()}
function renderQuizQuestion(){const q=activeQuiz[quizIndex];$('#quiz-runner').innerHTML=`<div class="runner-top"><strong>${esc(q.entry.subject)} practice</strong><span>${quizIndex+1} / ${activeQuiz.length}</span></div><div class="question-stem">${esc(q.stem)}</div><div class="options">${q.options.map((o,i)=>`<button class="option-btn" data-i="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><div id="quiz-feedback"></div>`;$('#quiz-runner').querySelectorAll('.option-btn').forEach(b=>b.onclick=()=>answerQuiz(+b.dataset.i))}
function answerQuiz(i){const q=activeQuiz[quizIndex],ok=i===q.answer;if(ok)quizScore++;else if(!state.review.includes(q.entry.id))state.review.push(q.entry.id);curriculumMasteryEvidence(q.entry,ok);noteMistakeResult(q,'curriculum',i,ok,'curriculum-quiz');save();renderMistakeNotebook();$('#quiz-runner').querySelectorAll('.option-btn').forEach((b,idx)=>{b.disabled=true;if(idx===q.answer)b.classList.add('correct');else if(idx===i)b.classList.add('wrong')});$('#quiz-feedback').innerHTML=`<div class="explanation"><strong>${ok?'Correct':'Review this topic'}</strong><p>${esc(q.explanation)}</p><button class="button primary compact" id="quiz-next">${quizIndex===activeQuiz.length-1?'Finish':'Next'}</button></div>`;$('#quiz-next').onclick=()=>{if(quizIndex<activeQuiz.length-1){quizIndex++;renderQuizQuestion()}else finishQuiz()}}
function finishQuiz(){state.quizHistory.push({date:new Date().toISOString(),score:quizScore,total:activeQuiz.length});save();$('#quiz-runner').classList.add('hidden');$('#quiz-result').classList.remove('hidden');$('#quiz-result').innerHTML=`<span class="small-label">Practice complete</span><h3>${quizScore} / ${activeQuiz.length}</h3><p>Missed topics were added to your review queue.</p><button class="button primary" id="quiz-again">Build another set</button>`;$('#quiz-again').onclick=()=>{$('#quiz-result').classList.add('hidden');$('#quiz-setup').classList.remove('hidden')};updateDashboard()}

// Workspace
function renderWorkspace(){const q=$('#workspace-search').value?.toLowerCase()||'',folder=$('#workspace-folder-filter').value||'all';const notes=state.workspaceNotes.filter(n=>(folder==='all'||n.folder===folder)&&(`${n.title} ${n.content}`.toLowerCase().includes(q)));$('#workspace-list').innerHTML=notes.length?notes.map(n=>`<button data-id="${n.id}" class="${activeWorkspaceId===n.id?'active':''}"><strong>${esc(n.title)}</strong><small>${esc(n.folder||'General')}</small></button>`).join(''):'<p class="muted">No notes yet.</p>';$('#workspace-list').querySelectorAll('button').forEach(b=>b.onclick=()=>openWorkspace(b.dataset.id));fillSelect($('#workspace-folder-filter'),['all',...state.folders],folder);fillSelect($('#workspace-folder'),state.folders,$('#workspace-folder').value||state.folders[0]);$('#folder-chips').innerHTML=state.folders.map(f=>`<span class="folder-chip">${esc(f)}</span>`).join('');rebuildDeckSources()}
function newWorkspace(){activeWorkspaceId='n'+Date.now();$('#workspace-title').value='Untitled note';$('#workspace-folder').value=state.folders[0];$('#workspace-source').value='';$('#workspace-editor').value='';}
function saveWorkspace(){if(!activeWorkspaceId)newWorkspace();const note={id:activeWorkspaceId,title:$('#workspace-title').value||'Untitled note',folder:$('#workspace-folder').value||'General',source:$('#workspace-source').value,content:$('#workspace-editor').value,updated:Date.now()};const i=state.workspaceNotes.findIndex(n=>n.id===activeWorkspaceId);i>=0?state.workspaceNotes[i]=note:state.workspaceNotes.unshift(note);save();renderWorkspace();toast('Note saved');if(roomChannel)roomChannel.postMessage({type:'note',note})}
function openWorkspace(id){const n=state.workspaceNotes.find(x=>x.id===id);if(!n)return;activeWorkspaceId=id;$('#workspace-title').value=n.title;$('#workspace-folder').value=n.folder||'General';$('#workspace-source').value=n.source||'';$('#workspace-editor').value=n.content;renderWorkspace()}
function deleteWorkspace(){if(!activeWorkspaceId)return;state.workspaceNotes=state.workspaceNotes.filter(n=>n.id!==activeWorkspaceId);activeWorkspaceId=null;save();newWorkspace();renderWorkspace()}
function addFolder(){const f=$('#new-folder-name').value.trim();if(f&&!state.folders.includes(f))state.folders.push(f);$('#new-folder-name').value='';save();renderWorkspace()}

function renderPlannerBoards(){fillSelect($('#planner-board'),['All',...uniq(STUDY_DATA.map(e=>e.board))],$('#planner-board').value||'All')}
function buildPlan(){const board=$('#planner-board').value,mins=+$('#daily-time').value;let pool=[...state.review.map(id=>STUDY_DATA.find(e=>e.id===id)).filter(Boolean),...STUDY_DATA.filter(e=>!state.completed.includes(e.id))];pool=pool.filter((e,i,a)=>a.findIndex(x=>x.id===e.id)===i&&(board==='All'||e.board===board));const per=Math.max(1,Math.round(mins/35));$('#planner-heading').textContent='Seven-day revision map';$('#planner-output').innerHTML=Array.from({length:7},(_,d)=>{const items=pool.slice(d*per,(d+1)*per);return `<div class="plan-day"><strong>Day ${d+1}</strong>${items.length?items.map(e=>`<p>${state.review.includes(e.id)?'Review':'Study'} · ${esc(e.subject)} · ${esc(e.title)}</p>`).join(''):'<p>Buffer, catch-up or SAT mixed practice.</p>'}</div>`}).join('')}
function updateDashboard(){const total=STUDY_DATA.length,done=state.completed.length,pct=Math.round(done/total*100),avg=state.quizHistory.length?Math.round(state.quizHistory.reduce((a,h)=>a+h.score/h.total,0)/state.quizHistory.length*100):0;$('#hero-percent').textContent=pct+'%';$('#hero-progress').style.width=pct+'%';$('#hero-completed').textContent=done;const reviewActions=smartReviewCandidates().total;$('#hero-review').textContent=reviewActions;$('#hero-average').textContent=state.quizHistory.length?avg+'%':'—';$('#metric-complete').textContent=pct+'%';$('#metric-total').textContent=total;$('#metric-average').textContent=state.quizHistory.length?avg+'%':'—';$('#metric-review').textContent=reviewActions;$('#subject-progress').innerHTML=uniq(STUDY_DATA.map(e=>e.board)).map(b=>{const all=STUDY_DATA.filter(e=>e.board===b),d=all.filter(e=>state.completed.includes(e.id)).length,p=Math.round(d/all.length*100);return `<div class="progress-row"><div class="progress-row-top"><span>${esc(b)}</span><strong>${p}%</strong></div><div class="mastery-bar"><span style="width:${p}%"></span></div></div>`}).join('');renderMasteryDashboard();renderMistakeNotebook();renderSrsDashboard();renderSmartReviewQueue();renderLists();updateSatSummary()}
function renderLists(){const row=(id,arr)=>{const es=arr.map(k=>STUDY_DATA.find(e=>e.id===k)).filter(Boolean);$(id).innerHTML=es.length?es.slice(0,20).map(e=>`<button data-id="${esc(e.id)}">${esc(e.title)}<small>${esc(e.board)} · ${esc(e.grade)}</small></button>`).join(''):'<p class="muted">Nothing here yet.</p>';$(id).querySelectorAll('button').forEach(b=>b.onclick=()=>jumpToEntry(b.dataset.id))};row('#bookmark-list',state.bookmarks);row('#review-list',state.review)}
function jumpToEntry(id){const e=STUDY_DATA.find(x=>x.id===id);if(!e)return;current={board:e.board,grade:e.grade,subject:e.subject,topic:e.title};renderFilters();openTopic(e.title);location.hash='#study'}
function tutor(){const q=$('#tutor-query').value,r=searchAll(q).slice(0,6);$('#tutor-answer').innerHTML=r.length?r.map(e=>`<div class="tutor-result"><strong>${esc(e.title)}</strong><p>${esc(e.summary)}</p><button data-id="${esc(e.id)}">Open note</button></div>`).join(''):'<p>I could not find that in the material stored locally. Try a topic name, formula keyword or concept.</p>';$('#tutor-answer').querySelectorAll('button').forEach(b=>b.onclick=()=>jumpToEntry(b.dataset.id))}
function speak(text,rate=1){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=rate;speechSynthesis.speak(u)}
function noteText(){const e=currentEntry();return e?`${e.title}. ${e.summary}. Key ideas: ${e.keyPoints.join('. ')}. ${e.formulas.join('. ')}`:''}
function shareText(txt){if(navigator.share)navigator.share({title:'StudyAI',text:txt}).catch(()=>{});else navigator.clipboard.writeText(txt).then(()=>toast('Copied to clipboard'))}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='studyai-backup.json';a.click();URL.revokeObjectURL(a.href)}
function importData(file){const r=new FileReader();r.onload=()=>{try{state={...defaults(),...JSON.parse(r.result)};save();location.reload()}catch{toast('Could not read backup')}};r.readAsText(file)}
function renderTimer(){$('#timer-display').textContent=`${String(Math.floor(timerSeconds/60)).padStart(2,'0')}:${String(timerSeconds%60).padStart(2,'0')}`}
function toggleTimer(){if(timerHandle){clearInterval(timerHandle);timerHandle=null;$('#timer-start').textContent='Start';return}$('#timer-start').textContent='Pause';timerHandle=setInterval(()=>{timerSeconds--;renderTimer();if(timerSeconds<=0){clearInterval(timerHandle);timerHandle=null;timerSeconds=25*60;renderTimer();toast('Focus block complete')}},1000)}
function joinRoom(){const code=$('#room-code').value.trim();if(!code)return toast('Enter a room code');if(!('BroadcastChannel' in window))return toast('Local study rooms are not supported in this browser');roomChannel=new BroadcastChannel('studyai-'+code);$('#room-status').textContent='Connected locally. Open another StudyAI tab and use the same code.';roomChannel.onmessage=e=>{if(e.data?.type==='note'){const n=e.data.note,i=state.workspaceNotes.findIndex(x=>x.id===n.id);i>=0?state.workspaceNotes[i]=n:state.workspaceNotes.unshift(n);save();renderWorkspace();toast('Study-room note updated')}}}
async function fetchJSON(url,options={}){
 const r=await fetch(url,options);let data={};try{data=await r.json()}catch{}
 if(!r.ok)throw new Error(data.error||'Request failed');return data
}
function userInitial(){return (cloudUser?.name||cloudUser?.email||'S').trim().charAt(0).toUpperCase()||'S'}
function renderAuth(){
 const signed=!!cloudUser;$('#auth-signed-out')?.classList.toggle('hidden',signed);$('#auth-signed-in')?.classList.toggle('hidden',!signed);
 if(signed){
  const label=cloudUser.name||cloudUser.email.split('@')[0];$('#account-label').textContent=label;$('#account-avatar').textContent=userInitial();$('#account-avatar-large').textContent=userInitial();$('#account-name').textContent=label;$('#account-email').textContent=cloudUser.email;$('#personal-storage-label').textContent='Saved locally · synced to your StudyAI account';
 }else{$('#account-label').textContent='Sign in';$('#account-avatar').textContent='S';$('#personal-storage-label').textContent='Saved locally · cloud synced when signed in'}
 $$('.social-auth').forEach(b=>{const ok=!!cloudProviders[b.dataset.provider];b.classList.toggle('unavailable',!ok);b.querySelector('small').textContent=ok?'':'Setup required';b.setAttribute('aria-disabled',String(!ok))})
}
function setAuthMode(mode){
 authMode=mode;const reg=mode==='register';$('#auth-login-tab').classList.toggle('active',!reg);$('#auth-register-tab').classList.toggle('active',reg);$('#auth-name-field').classList.toggle('hidden',!reg);$('#auth-submit').textContent=reg?'Create account':'Sign in';$('#auth-password').autocomplete=reg?'new-password':'current-password';setPasswordVisible(false,{animate:false});$('#auth-error').classList.add('hidden');
}
function showAuthError(message){const e=$('#auth-error');e.textContent=message;e.classList.remove('hidden')}
async function hydrateCloudState(){
 if(!cloudUser)return;
 try{
  const data=await fetchJSON('/api/state');
  if(data.has_state&&data.state){
   const remote={...defaults(),...data.state};
   if(JSON.stringify(remote)!==JSON.stringify(state)){
    localStorage.setItem(STORAGE_KEY,JSON.stringify(remote));setSyncUI('saved','Restoring your account…');location.reload();return;
   }
   setSyncUI('saved','Up to date · saved to your account');
  }else{await saveCloudState(false)}
 }catch{setSyncUI('error','Could not load cloud data. Your local copy is safe.')}
}
async function initAuth(){
 try{
  const data=await fetchJSON('/api/auth/me');cloudUser=data.user;cloudProviders=data.providers||{};renderAuth();
  const params=new URLSearchParams(location.search);
  if(params.get('auth_error')){showAuthError(params.get('auth_error')==='provider_not_configured'?'That sign-in provider still needs developer credentials.':'Social sign-in could not be completed.');$('#auth-dialog').showModal()}
  if(cloudUser)await hydrateCloudState();
  if(params.has('auth')||params.has('auth_error'))history.replaceState({},'',location.pathname+location.hash);
 }catch{cloudUser=null;cloudProviders={};renderAuth();setSyncUI('error','Account server unavailable · using local mode')}
}
function buildPasswordDust(){
 const dust=$('#password-dust');if(!dust||dust.childElementCount)return;
 for(let i=0;i<28;i++){
  const p=document.createElement('i');
  const x=4+(i/27)*82+(Math.random()*3-1.5);
  const size=2+Math.random()*3.2;
  const dx=(Math.random()*46+14)*(Math.random()<.5?-1:1);
  const dy=(Math.random()*44-22);
  p.style.setProperty('--x',`${x}%`);p.style.setProperty('--s',`${size}px`);p.style.setProperty('--dx',`${dx}px`);p.style.setProperty('--dy',`${dy}px`);p.style.setProperty('--d',`${360+Math.random()*220}ms`);p.style.setProperty('--delay',`${Math.random()*90}ms`);dust.appendChild(p)
 }
}
function setPasswordVisible(show,{animate=true}={}){
 const shell=$('#password-shell'),input=$('#auth-password'),button=$('#password-toggle'),text=$('#password-toggle-text');if(!shell||!input||!button)return;
 const finish=()=>{input.type=show?'text':'password';shell.classList.toggle('password-revealed',show);button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',show?'Hide password':'Show password');text.textContent=show?'Hide':'Show'};
 shell.classList.remove('dusting','concealing');
 if(!animate||window.matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return}
 if(show){buildPasswordDust();shell.classList.add('dusting');setTimeout(finish,105);setTimeout(()=>shell.classList.remove('dusting'),680)}
 else{shell.classList.add('concealing');finish();setTimeout(()=>shell.classList.remove('concealing'),300)}
}
function togglePasswordVisibility(){setPasswordVisible($('#auth-password').type==='password')}
function bindAuth(){
 const dialog=$('#auth-dialog');$('#account-button').onclick=()=>dialog.showModal();$('#auth-close').onclick=()=>dialog.close();$('#auth-login-tab').onclick=()=>setAuthMode('login');$('#auth-register-tab').onclick=()=>setAuthMode('register');$('#password-toggle').onclick=togglePasswordVisibility;
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const btn=$('#auth-submit');btn.disabled=true;btn.textContent=authMode==='register'?'Creating account…':'Signing in…';$('#auth-error').classList.add('hidden');try{
  const payload={email:$('#auth-email').value.trim(),password:$('#auth-password').value,name:$('#auth-name').value.trim()};
  const data=await fetchJSON(authMode==='register'?'/api/auth/register':'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});cloudUser=data.user;renderAuth();await hydrateCloudState();dialog.close();toast(authMode==='register'?'Account created · progress synced':'Welcome back');
 }catch(err){showAuthError(err.message)}finally{btn.disabled=false;btn.textContent=authMode==='register'?'Create account':'Sign in'}};
 $$('.social-auth').forEach(b=>b.onclick=()=>{const p=b.dataset.provider;if(!cloudProviders[p])return showAuthError(`${p[0].toUpperCase()+p.slice(1)} sign-in needs its developer credentials configured first.`);location.href=`/auth/${p}`});
 $('#sync-now').onclick=()=>saveCloudState(true);$('#logout-button').onclick=async()=>{await fetchJSON('/api/auth/logout',{method:'POST'}).catch(()=>{});cloudUser=null;state={...defaults(),theme:state.theme};localStorage.setItem(STORAGE_KEY,JSON.stringify(state));renderAuth();dialog.close();toast('Signed out · account data remains stored');setTimeout(()=>location.reload(),380)};
 setAuthMode('login');
}
function initMotion(){
 const targets=$$('.section,.feature-strip');targets.forEach(el=>el.classList.add('motion-reveal'));
 if(!('IntersectionObserver'in window)){targets.forEach(el=>el.classList.add('motion-in'));return}
 const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('motion-in');obs.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -40px'});targets.forEach(el=>obs.observe(el));
}
